fetch(new URL("products.json",document.querySelector('script[src*="app.js"]')?.src||window.location.href),{cache:"no-store"}).then(r=>{if(!r.ok)throw new Error("Falha ao carregar products.json: HTTP "+r.status);return r.json()}).then(data=>{if(!Array.isArray(data)||!data.length)throw new Error("O cadastro de produtos está vazio ou inválido.");allProducts=data;buildTabs();renderProducts();renderCart()}).catch(err=>{console.error("Usando cadastro de produtos integrado porque products.json não carregou:",err);allProducts=FALLBACK_PRODUCTS;buildTabs();renderProducts();renderCart()});
function buildTabs(){const cats=["Todos",...new Set(allProducts.map(p=>p.category))];$("tabs").innerHTML=cats.map(c=>`<button class="tab ${c===activeCategory?"active":""}" data-cat="${c}">${c}</button>`).join("");const groups=activeCategory==="Todos"?[]:[...new Set(allProducts.filter(p=>p.category===activeCategory&&p.group).map(p=>p.group))];$("subTabs").hidden=!groups.length;$("subTabs").innerHTML=groups.length?[`<button class="tab ${activeGroup==="Todos"?"active":""}" data-group="Todos">Todos os modelos</button>`,...groups.map(g=>`<button class="tab ${g===activeGroup?"active":""}" data-group="${g}">${g}</button>`)].join(""):"";}
function renderProducts(){let q=$("search").value.toLocaleLowerCase("pt-BR").trim();let arr=allProducts.filter(p=>(activeCategory==="Todos"||p.category===activeCategory)&&(activeGroup==="Todos"||p.group===activeGroup)&&(p.name+" "+p.desc+" "+(p.flavors||[]).join(" ")).toLocaleLowerCase("pt-BR").includes(q));let sort=$("sort").value;if(sort==="price-up")arr.sort((a,b)=>(a.price??Infinity)-(b.price??Infinity));if(sort==="price-down")arr.sort((a,b)=>(b.price??-Infinity)-(a.price??-Infinity));if(sort==="name")arr.sort((a,b)=>a.name.localeCompare(b.name,"pt-BR"));$("products").innerHTML=arr.length?arr.map(p=>`<article class="card"><div class="photo">${p.image ? '<img src="' + p.image + '" alt="' + p.name + '" loading="lazy" >' : (p.icon||"🛍️")}</div><span class="tag">${p.category}</span><h3>${p.name}</h3><p>${p.desc}</p><div class="price">${p.price==null?"Consulte":money(p.price)}</div><div class="unit">${p.unit}</div>${p.price==null?`<button class="add" data-quote="${p.id}">Consultar no WhatsApp</button>`:`<button class="add" data-add="${p.id}">＋ Adicionar ao pedido</button>`}</article>`).join(""):'<p class="empty">Nenhum produto encontrado nesta categoria.</p>';document.querySelectorAll("[data-cat]").forEach(b=>b.classList.toggle("active",b.dataset.cat===activeCategory));document.querySelectorAll("[data-group]").forEach(b=>b.classList.toggle("active",b.dataset.group===activeGroup));}
function renderCart(){let arr=allProducts.filter(p=>bag[p.id]);$("count").textContent=Object.values(bag).reduce((a,b)=>a+b,0);$("cartLines").innerHTML=arr.length?arr.map(p=>`<div class="line"><span>${p.name}<br><b>${money(p.price*bag[p.id])}</b><br><small>${p.unit}</small></span><span class="qty"><button data-minus="${p.id}" aria-label="Diminuir">−</button>${bag[p.id]}<button data-plus="${p.id}" aria-label="Aumentar">＋</button></span></div>`).join(""):'<p style="color:#637b91">Seu pedido está vazio.</p>';$("total").textContent=money(arr.reduce((s,p)=>s+p.price*bag[p.id],0))}
document.addEventListener("click",e=>{let add=e.target.closest("[data-add]"),plus=e.target.closest("[data-plus]"),minus=e.target.closest("[data-minus]"),cat=e.target.closest("[data-cat]"),grp=e.target.closest("[data-group]"),quote=e.target.closest("[data-quote]");if(quote){let p=allProducts.find(x=>x.id===quote.dataset.quote);let msg="Olá, Águajá Gelajá! Gostaria de consultar preço e disponibilidade: "+(p?.name||"produto do catálogo");if(p?.flavors?.length)msg+="\n\nSabores de interesse: "+p.flavors.join(", ");window.open("https://wa.me/5567981430628?text="+encodeURIComponent(msg)," _blank".trim(),"noopener")}if(add){let id=add.dataset.add;bag[id]=(bag[id]||0)+1;$("cart").classList.remove("hidden");renderCart()}if(plus){let id=plus.dataset.plus;bag[id]=(bag[id]||0)+1;renderCart()}if(minus){let id=minus.dataset.minus;bag[id]--;if(bag[id]<=0)delete bag[id];renderCart()}if(cat){activeCategory=cat.dataset.cat;activeGroup="Todos";buildTabs();renderProducts()}if(grp){activeGroup=grp.dataset.group;buildTabs();renderProducts()}});
$("search").addEventListener("input",renderProducts);$("sort").addEventListener("change",renderProducts);$("openCart").addEventListener("click",()=>$("cart").classList.toggle("hidden"));$("closeCart").addEventListener("click",()=>$("cart").classList.add("hidden"));$("year").textContent=new Date().getFullYear();
$("send").addEventListener("click",()=>{let arr=allProducts.filter(p=>bag[p.id]);if(!arr.length){alert("Adicione ao menos um produto ao pedido.");return}let total=arr.reduce((s,p)=>s+p.price*bag[p.id],0);let lines=arr.map(p=>`- ${p.name} (${p.unit}) | Quantidade: ${bag[p.id]} | ${money(p.price*bag[p.id])}`).join("\n");let msg="Olá, Águajá Gelajá! Gostaria de fazer este pedido:\n\n"+lines+"\n\nTotal estimado: "+money(total)+"\n\nPodem confirmar a disponibilidade, a taxa de entrega e o valor final, por favor?";window.open("https://wa.me/5567981430628?text="+encodeURIComponent(msg),"_blank","noopener")});